import random
import string
from typing import List

# Generator for DNS zone origin strings (owner names) with valid syntax and varied structures.
# Focus: create short (<128 bytes) names with combinations that exercise absolute/relative,
# single/multiple labels, numeric-only labels, hyphens, underscores (some parsers reject),
# punycode-like labels, and edge lengths near 63 label and ~255 total. Also include empty string
# to represent root and single dot.

DNS_LABEL_CHARS = string.ascii_lowercase + string.digits + "-"


def _rand_label(rng: random.Random, min_len: int = 1, max_len: int = 20) -> str:
    # Generate a label conforming to LDH rule: start/end alnum, hyphens allowed inside.
    # Ensure not starting/ending with '-'.
    L = rng.randint(min_len, max_len)
    if L == 1:
        return rng.choice(string.ascii_lowercase + string.digits)
    # Build first and last as alnum
    first = rng.choice(string.ascii_lowercase + string.digits)
    last = rng.choice(string.ascii_lowercase + string.digits)
    if L <= 2:
        return first + (last if L == 2 else "")
    mid_len = L - 2
    mid = ''.join(rng.choice(DNS_LABEL_CHARS) for _ in range(mid_len))
    return first + mid + last


def _rand_numeric_label(rng: random.Random, min_len: int = 1, max_len: int = 10) -> str:
    L = rng.randint(min_len, max_len)
    return ''.join(rng.choice(string.digits) for _ in range(L))


def _rand_hyphenated_label(rng: random.Random, total_len: int) -> str:
    # Make sure first/last are letters, with hyphens inside.
    if total_len < 3:
        return _rand_label(rng, total_len, total_len)
    first = rng.choice(string.ascii_lowercase)
    last = rng.choice(string.ascii_lowercase + string.digits)
    mid = ''.join(rng.choice(string.ascii_lowercase + string.digits + '-') for _ in range(total_len - 2))
    # Avoid hyphen at end
    if mid and mid[-1] == '-':
        mid = mid[:-1] + rng.choice(string.ascii_lowercase + string.digits)
    return first + mid + last


def _rand_punycode_like(rng: random.Random, max_len: int = 20) -> str:
    # xn-- prefix with LDH payload
    base_len = rng.randint(1, max_len - 4)
    payload = _rand_label(rng, base_len, base_len)
    # ensure payload contains at least one hyphen sometimes
    if '-' not in payload and base_len > 3 and rng.random() < 0.5:
        i = rng.randint(1, base_len - 2)
        payload = payload[:i] + '-' + payload[i+1:]
    return 'xn--' + payload


def _compose_name(rng: random.Random) -> str:
    # Choose a style
    style = rng.choice([
        'root',            # empty => root, or just '.'
        'single',          # single label
        'absolute',        # multiple labels ending with dot
        'relative',        # multiple labels without trailing dot
        'near63',          # include 63-byte label boundary
        'numeric',         # numeric-only label(s)
        'punycode',        # punycode-like
        'mixed',           # mixed types
    ])

    if style == 'root':
        return '' if rng.random() < 0.5 else '.'

    labels: List[str] = []

    if style == 'single':
        labels = [_rand_label(rng, 1, rng.randint(3, 20))]

    elif style == 'absolute':
        n = rng.randint(2, 5)
        for _ in range(n):
            pick = rng.random()
            if pick < 0.1:
                labels.append(_rand_numeric_label(rng))
            elif pick < 0.2:
                labels.append(_rand_punycode_like(rng))
            else:
                labels.append(_rand_label(rng, 1, 15))

    elif style == 'relative':
        n = rng.randint(2, 6)
        labels = [_rand_label(rng, 1, rng.randint(3, 15)) for _ in range(n)]

    elif style == 'near63':
        # Create a label close to 63 bytes
        L = rng.randint(60, 63)
        labels = [_rand_hyphenated_label(rng, L)]
        # add a couple of small labels
        for _ in range(rng.randint(0, 2)):
            labels.append(_rand_label(rng, 1, 5))

    elif style == 'numeric':
        n = rng.randint(1, 4)
        labels = [_rand_numeric_label(rng, 1, 10) for _ in range(n)]

    elif style == 'punycode':
        n = rng.randint(1, 3)
        labels = [_rand_punycode_like(rng, 20) for _ in range(n)]

    elif style == 'mixed':
        n = rng.randint(2, 6)
        for _ in range(n):
            pick = rng.random()
            if pick < 0.15:
                labels.append(_rand_numeric_label(rng, 1, 8))
            elif pick < 0.3:
                labels.append(_rand_punycode_like(rng, 20))
            else:
                labels.append(_rand_label(rng, 1, 20))

    name = '.'.join(labels)
    # Decide absolute vs relative for non-root styles; absolute more often
    if style in ('absolute', 'near63', 'punycode', 'mixed'):
        if not name.endswith('.'):
            name += '.'
    else:
        if rng.random() < 0.4:
            name += '.'

    # Cap to 128 bytes as harness may resize; try trimming by dropping labels from the left if needed.
    if len(name) > 120:
        parts = name.rstrip('.').split('.')
        while parts and len('.'.join(parts)) + 1 > 120:  # +1 maybe trailing dot
            parts.pop(0)
        name = '.'.join(parts)
        if rng.random() < 0.5:
            name += '.'
    return name


def _encode_param_stream(origin: str, rclass: int, ttl: int, flags: int) -> bytes:
    # The fuzzer harness pulls multiple FUZZ_PARAM(unsigned int) along with FUZZ_PARAM_STR.
    # We provide a simple stream format so the engine can slice parameters sequentially:
    # [4B magic]\n[1B choice]\n[2B rclass]\n[4B ttl]\n[4B flags]\n[2B name_len]\n[name bytes]
    # All integer fields little-endian. This is arbitrary but consistent.
    magic = b'ZSCN'  # recognizable header
    choice = bytes([0])  # reserved
    rclass_b = int(rclass & 0xFFFF).to_bytes(2, 'little')
    ttl_b = int(ttl & 0xFFFFFFFF).to_bytes(4, 'little')
    flags_b = int(flags & 0xFFFFFFFF).to_bytes(4, 'little')
    name_bytes = origin.encode('ascii', errors='ignore')
    if len(name_bytes) > 128:
        name_bytes = name_bytes[:128]
    name_len_b = len(name_bytes).to_bytes(2, 'little')
    return b''.join([magic, choice, rclass_b, ttl_b, flags_b, name_len_b, name_bytes])


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide origin generation path
    origin = _compose_name(rng)

    # Flags: influence origin selection in harness
    # bit0 -> empty string, bit1 -> NULL, otherwise use origin string.
    # Generate combinations to exercise both paths. Avoid both bits set at once sometimes.
    pick = rng.random()
    if origin == '' or origin == '.':
        # If we already chose root-like, set bit0 sometimes to enforce empty string path
        flags = 1 if rng.random() < 0.7 else 0
    else:
        if pick < 0.15:
            flags = 1  # force empty string
        elif pick < 0.25:
            flags = 2  # force NULL
        else:
            flags = 0

    # rclass: pick common DNS classes and random others
    common_classes = [1, 3, 4, 254, 255]  # IN, CH, HS, none/private, ANY
    if rng.random() < 0.6:
        rclass = rng.choice(common_classes)
    else:
        rclass = rng.randrange(0, 65536)

    # ttl: choose typical TTLs and some extremes
    typical_ttls = [0, 60, 300, 3600, 86400, 2**32 - 1]
    ttl = rng.choice(typical_ttls) if rng.random() < 0.6 else rng.randrange(0, 2**32)

    buf = _encode_param_stream(origin, rclass, ttl, flags)
    # Ensure total size <= 4096
    return buf[:4096]

import random
import string
from typing import List, Tuple

# Generator for valid DNS zone file text inputs (bytes)
# Aims to cover: $ORIGIN/$TTL directives, comments, various RR types (A, AAAA, NS, CNAME,
# MX, TXT, SOA, SRV, PTR, CAA, NAPTR, TLSA, LOC, SVCB/HTTPS, HINFO, SPF),
# multi-line records with parentheses, escaped text, base64/hex, and different classes/TTLs.
# Output length is capped to 4096 bytes by design of assembly.

DNS_LABEL_CHARS = string.ascii_lowercase + string.digits + "-"

CLASSES = ["IN", "CH", "HS"]
TYPES_COMMON = [
    "A", "AAAA", "NS", "CNAME", "MX", "TXT", "SOA", "SRV", "PTR", "CAA",
    "NAPTR", "TLSA", "LOC", "SVCB", "HTTPS", "HINFO", "SPF"
]

# Helpers

def rint(r: random.Random, a: int, b: int) -> int:
    return r.randint(a, b)

def rchoice(r: random.Random, seq):
    return seq[r.randrange(len(seq))]

def label(r: random.Random, min_len=1, max_len=10) -> str:
    # Generate a valid DNS label (no leading/trailing dash, <=63)
    L = rint(r, min_len, max_len)
    if L == 1:
        return rchoice(r, string.ascii_lowercase + string.digits)
    middle_len = max(0, L - 2)
    mid_chars = ''.join(rchoice(r, DNS_LABEL_CHARS) for _ in range(middle_len))
    start = rchoice(r, string.ascii_lowercase + string.digits)
    end = rchoice(r, string.ascii_lowercase + string.digits)
    return start + mid_chars + end

def dname(r: random.Random, absolute=True, depth=None) -> str:
    if depth is None:
        depth = rint(r, 1, 4)
    parts = [label(r) for _ in range(depth)]
    name = '.'.join(parts)
    if absolute:
        name += '.'
    return name

def ipv4(r: random.Random) -> str:
    return '.'.join(str(rint(r, 0, 255)) for _ in range(4))

def ipv6_block(r: random.Random) -> str:
    return format(rint(r, 0, 0xFFFF), 'x')

def ipv6(r: random.Random) -> str:
    # Simplified but valid compressed forms
    if r.random() < 0.5:
        # full 8 blocks
        return ':'.join(format(rint(r, 0, 0xFFFF), 'x') for _ in range(8))
    else:
        # compressed with ::
        left = rint(r, 0, 6)
        right = rint(r, 0, 6 - left)
        left_part = ':'.join(ipv6_block(r) for _ in range(left))
        right_part = ':'.join(ipv6_block(r) for _ in range(right))
        if left == 0 and right == 0:
            return '::'
        if left == 0:
            return '::' + right_part
        if right == 0:
            return left_part + '::'
        return left_part + '::' + right_part

def ttl_text(r: random.Random) -> str:
    # Mix numeric and unit forms
    options = []
    options.append(str(rint(r, 0, 86400)))
    units = ['S', 'M', 'H', 'D', 'W']
    val = []
    # up to 3 unit segments
    for _ in range(rint(r, 1, 3)):
        val.append(str(rint(r, 1, 48)) + rchoice(r, units))
    options.append(''.join(val))
    return rchoice(r, options)

def maybe_comment(r: random.Random) -> str:
    if r.random() < 0.4:
        txt = ''.join(rchoice(r, string.ascii_letters + string.digits + ' .-_') for _ in range(rint(r, 3, 30)))
        return ' ; ' + txt
    return ''

def txt_chunk(r: random.Random) -> str:
    # Quoted text with possible escapes
    length = rint(r, 0, 32)
    chars = []
    for _ in range(length):
        ch = rchoice(r, string.ascii_letters + string.digits + ' !#$%&\'()*+,-./:;<=>?@[]^_`{|}~')
        if ch in ['"', '\\'] and r.random() < 0.7:
            chars.append('\\' + ch)
        else:
            chars.append(ch)
    return '"' + ''.join(chars) + '"'

def base64_blob(r: random.Random) -> str:
    alphabet = string.ascii_letters + string.digits + '+/'
    # Size multiple of 4 after padding
    groups = rint(r, 1, 12)
    data = ''.join(rchoice(r, alphabet) for _ in range(groups * 4))
    # Random padding correctness is okay since blobs are just text here
    if r.random() < 0.5:
        data = data[:-rint(r, 0, 2)] + '=' * rint(r, 0, 2)
    return data

def hex_blob(r: random.Random) -> str:
    size = rint(r, 1, 32)
    return ''.join(rchoice(r, '0123456789ABCDEF') for _ in range(size * 2))

def soa_rr(r: random.Random, owner: str, cls: str, ttl: str) -> str:
    mname = dname(r)
    rname = dname(r)
    serial = rint(r, 1, 2**31 - 1)
    refresh = rint(r, 60, 86400)
    retry = rint(r, 30, 3600)
    expire = rint(r, 3600, 2419200)
    minimum = rint(r, 60, 86400)
    if r.random() < 0.5:
        # multi-line parenthesized
        return f"{owner}\t{ttl}\t{cls}\tSOA\t{mname} {rname} (\n\t{serial} ; serial\n\t{refresh} ; refresh\n\t{retry} ; retry\n\t{expire} ; expire\n\t{minimum} )" + maybe_comment(r)
    else:
        return f"{owner}\t{ttl}\t{cls}\tSOA\t{mname} {rname} {serial} {refresh} {retry} {expire} {minimum}" + maybe_comment(r)

def mx_rr(r: random.Random, owner: str, cls: str, ttl: str) -> str:
    pref = rint(r, 0, 50)
    host = dname(r)
    return f"{owner}\t{ttl}\t{cls}\tMX\t{pref} {host}" + maybe_comment(r)

def txt_rr(r: random.Random, owner: str, cls: str, ttl: str, typ="TXT") -> str:
    # multiple chunks allowed
    chunks = [txt_chunk(r) for _ in range(rint(r, 1, 3))]
    return f"{owner}\t{ttl}\t{cls}\t{typ}\t" + ' '.join(chunks) + maybe_comment(r)

def a_rr(r: random.Random, owner: str, cls: str, ttl: str) -> str:
    return f"{owner}\t{ttl}\t{cls}\tA\t{ipv4(r)}" + maybe_comment(r)

def aaaa_rr(r: random.Random, owner: str, cls: str, ttl: str) -> str:
    return f"{owner}\t{ttl}\t{cls}\tAAAA\t{ipv6(r)}" + maybe_comment(r)

def ns_rr(r: random.Random, owner: str, cls: str, ttl: str) -> str:
    return f"{owner}\t{ttl}\t{cls}\tNS\t{dname(r)}" + maybe_comment(r)

def cname_rr(r: random.Random, owner: str, cls: str, ttl: str) -> str:
    return f"{owner}\t{ttl}\t{cls}\tCNAME\t{dname(r)}" + maybe_comment(r)

def ptr_rr(r: random.Random, owner: str, cls: str, ttl: str) -> str:
    return f"{owner}\t{ttl}\t{cls}\tPTR\t{dname(r)}" + maybe_comment(r)

def srv_rr(r: random.Random, owner: str, cls: str, ttl: str) -> str:
    prio = rint(r, 0, 10)
    weight = rint(r, 0, 100)
    port = rint(r, 1, 65535)
    target = dname(r)
    return f"{owner}\t{ttl}\t{cls}\tSRV\t{prio} {weight} {port} {target}" + maybe_comment(r)

def caa_rr(r: random.Random, owner: str, cls: str, ttl: str) -> str:
    flags = rint(r, 0, 255)
    tag = rchoice(r, ["issue", "issuewild", "iodef"])
    if tag == "iodef":
        val = txt_chunk(r)
    else:
        val = '"' + (";".join([dname(r, absolute=False) for _ in range(rint(r, 1, 2))])) + '"'
    return f"{owner}\t{ttl}\t{cls}\tCAA\t{flags} {tag} {val}" + maybe_comment(r)

def naptr_rr(r: random.Random, owner: str, cls: str, ttl: str) -> str:
    order = rint(r, 0, 65535)
    pref = rint(r, 0, 65535)
    flags = txt_chunk(r)
    service = txt_chunk(r)
    regexp = txt_chunk(r)
    replacement = dname(r)
    return f"{owner}\t{ttl}\t{cls}\tNAPTR\t{order} {pref} {flags} {service} {regexp} {replacement}" + maybe_comment(r)

def tlsa_rr(r: random.Random, owner: str, cls: str, ttl: str) -> str:
    usage = rint(r, 0, 3)
    selector = rint(r, 0, 1)
    mtype = rint(r, 0, 2)
    blob = hex_blob(r)
    return f"{owner}\t{ttl}\t{cls}\tTLSA\t{usage} {selector} {mtype} {blob}" + maybe_comment(r)

def loc_rr(r: random.Random, owner: str, cls: str, ttl: str) -> str:
    # latitude/longitude in D M S with N/S and E/W, altitude m, size/hp/vp optional
    degN = rint(r, 0, 89)
    minN = rint(r, 0, 59)
    secN = rint(r, 0, 59)
    degE = rint(r, 0, 179)
    minE = rint(r, 0, 59)
    secE = rint(r, 0, 59)
    alt = rint(r, -100, 884800) / 100.0
    size = f"{rint(r, 1, 9000)/100.0}m"
    hp = f"{rint(r, 1, 9000)/100.0}m"
    vp = f"{rint(r, 1, 9000)/100.0}m"
    core = f"{degN} {minN} {secN} N {degE} {minE} {secE} E {alt}m {size} {hp} {vp}"
    if r.random() < 0.5:
        # multi-line variant inside parentheses
        return f"{owner}\t{ttl}\t{cls}\tLOC\t( {core} )" + maybe_comment(r)
    return f"{owner}\t{ttl}\t{cls}\tLOC\t{core}" + maybe_comment(r)

def svcb_rr(r: random.Random, owner: str, cls: str, ttl: str, typ: str) -> str:
    # Minimal valid SVCB/HTTPS: priority, target, params list
    priority = rint(r, 0, 4)
    target = dname(r)
    params = []
    # Include a mix of known params
    if r.random() < 0.8:
        params.append(f"alpn=\"h2,h3\"")
    if r.random() < 0.7:
        params.append(f"port={rint(r,1,65535)}")
    if r.random() < 0.6:
        ip = ipv4(r)
        params.append(f"ipv4hint={ip}")
    if r.random() < 0.6:
        params.append(f"ipv6hint={ipv6(r)}")
    if r.random() < 0.5:
        params.append(f"mandatory=alpn,port")
    if r.random() < 0.4:
        params.append(f"echconfig={base64_blob(r)}")
    plist = ' '.join(params)
    return f"{owner}\t{ttl}\t{cls}\t{typ}\t{priority} {target} {plist}".rstrip() + maybe_comment(r)

def hinfo_rr(r: random.Random, owner: str, cls: str, ttl: str) -> str:
    cpu = txt_chunk(r)
    os = txt_chunk(r)
    return f"{owner}\t{ttl}\t{cls}\tHINFO\t{cpu} {os}" + maybe_comment(r)


def spf_rr(r: random.Random, owner: str, cls: str, ttl: str) -> str:
    # SPF is like TXT
    return txt_rr(r, owner, cls, ttl, typ="SPF")


def records_for_owner(r: random.Random, owner: str, cls: str, ttl: str) -> List[str]:
    recs = []
    # Always include A/AAAA for coverage
    recs.append(a_rr(r, owner, cls, ttl))
    recs.append(aaaa_rr(r, owner, cls, ttl))
    # Random subset of other types
    gens = [
        ns_rr, cname_rr, mx_rr, txt_rr, soa_rr, srv_rr, ptr_rr, caa_rr,
        naptr_rr, tlsa_rr, loc_rr, hinfo_rr, spf_rr,
    ]
    # Add SVCB/HTTPS occasionally
    def add_svcb_like():
        recs.append(svcb_rr(r, owner, cls, ttl, typ=rchoice(r, ["SVCB", "HTTPS"])) )
    if r.random() < 0.8:
        add_svcb_like()
    for g in gens:
        if r.random() < 0.6:
            recs.append(g(r, owner, cls, ttl))
    return recs


def make_directives(r: random.Random) -> List[str]:
    lines = []
    # Optional initial comment
    if r.random() < 0.7:
        lines.append("; Generated zone for fuzz seeding")
    # $ORIGIN and $TTL directives
    if r.random() < 0.9:
        origin = dname(r)
        lines.append(f"$ORIGIN {origin}")
    if r.random() < 0.9:
        lines.append(f"$TTL {ttl_text(r)}")
    return lines


def make_owner_names(r: random.Random) -> List[str]:
    owners = [dname(r), dname(r), label(r) + '.']  # include a short absolute and a relative possibility
    # Also root owner sometimes
    if r.random() < 0.3:
        owners.append('.')
    return owners


def assemble_zone(r: random.Random) -> str:
    lines: List[str] = []
    lines.extend(make_directives(r))

    cls = rchoice(r, CLASSES)
    ttl = ttl_text(r)

    owners = make_owner_names(r)

    # SOA at apex to be realistic
    apex = owners[0]
    lines.append(soa_rr(r, apex, cls, ttl))

    # Per-owner records
    for owner in owners:
        for rr in records_for_owner(r, owner, cls, ttl):
            lines.append(rr)
        # Add an owner-specific $TTL or $ORIGIN sometimes to test directives interleaving
        if r.random() < 0.3:
            lines.append(f"$TTL {ttl_text(r)}")
        if r.random() < 0.2:
            lines.append(f"$ORIGIN {dname(r)}")
        # Add comments
        if r.random() < 0.5:
            lines.append("; comment for owner " + owner)

    # Add a multi-line TXT using parentheses to exercise long_string/comma_list behavior
    owner = rchoice(r, owners)
    chunks = [txt_chunk(r) for _ in range(rint(r, 2, 5))]
    txt_ml = '(\n    ' + '\n    '.join(chunks) + '\n)'
    lines.append(f"{owner}\t{ttl}\t{cls}\tTXT\t{txt_ml}")

    # Add a record with escaped domain labels via \DDD form
    esc_label = ''.join(['\\' + f"{rint(r,0,255):03d}" for _ in range(rint(r, 1, 3))])
    esc_name = esc_label + '.' + label(r) + '.'
    lines.append(a_rr(r, esc_name, cls, ttl))

    # Base64/hex carrying types via generic RDATA containers (e.g., TLSA already uses hex)
    owner2 = rchoice(r, owners)
    lines.append(f"{owner2}\t{ttl}\t{cls}\tSPF\t{txt_chunk(r)} {txt_chunk(r)}")

    # Ensure not exceeding size: join and trim by lines if necessary
    zone_text = '\n'.join(lines) + '\n'
    if len(zone_text) > 4000:
        # Keep head and tail
        head = zone_text[:2000]
        tail = zone_text[-1800:]
        zone_text = head + '\n; truncated for size' + '\n' + tail
    return zone_text


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Randomize seed slightly each call for variety while being based on provided seed
    seed2 = (seed * 1103515245 + 12345) & 0x7fffffff
    r.seed(seed2)
    zone = assemble_zone(r)
    # Ensure under 4096 bytes
    data = zone.encode('utf-8')[:4096]
    return data
